.usage-meter .usage-meter__legend-row { display: grid; grid-template-columns: 8px minmax(0, 1fr) max-content 40px; align-items: center; gap: 10px; width: calc(100% + 16px); min-height: 30px; margin: 0 -8px; padding: 0 8px; border: 0; border-radius: 8px; background: transparent; color: var(--um-text); text-align: left; font-size: 13px; line-height: 1.45; }
