 .usage-meter__readout { position: absolute; left: 0; bottom: calc(100% + 6px); z-index: 2; display: grid; gap: 1px; width: max-content; max-width: 100%; padding: 7px 10px; border: 1px solid var(--um-line); border-radius: 10px; background: var(--um-surface); color: var(--um-text); box-shadow: 0 8px 24px -6px #00000029, 0 2px 6px #0000000f; font-size: 13px; line-height: 1.45; pointer-events: none; opacity: 0; transition: left 260ms cubic-bezier(.22,1,.36,1), transform 260ms cubic-bezier(.22,1,.36,1), opacity 160ms; }
