.usage-meter .usage-meter__upgrade { position: relative; display: inline-grid; place-items: center; min-height: 32px; max-width: 100%; padding: 0 14px; border: 0; border-radius: 14px; background: var(--um-solid); color: var(--um-solid-text); box-shadow: 0 1px 2px #0000001f, 0 6px 14px -6px #00000059; font-size: 13px; font-weight: 500; line-height: 1.45; transition: background-color 280ms, color 280ms, box-shadow 280ms, transform 140ms; }
