@container usage-meter (max-width: 400px) {
  .usage-meter__header { flex-direction: column; gap: 12px; }
  .usage-meter__identity { width: 100%; }
  .usage-meter__periods { width: 100%; }
  .usage-meter .usage-meter__period { flex: 1; }
  .usage-meter__limits { grid-template-columns: minmax(0, 1fr); gap: 14px; }
  .usage-meter__limit { display: grid; grid-template-columns: minmax(0, 1fr) max-content; align-items: baseline; gap: 0 12px; }
  .usage-meter__limit-track { grid-column: 1 / -1; width: 100%; margin-top: 6px; }
